// HasOrder applies the HasEdge predicate on the "order" edge.
func HasOrder() predicate.TravelFulfillment {
	return predicate.TravelFulfillment(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, OrderTable, OrderColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasOrderWith applies the HasEdge predicate on the "order" edge with a given conditions (other predicates).
func HasOrderWith(preds ...predicate.TravelOrder) predicate.TravelFulfillment {
	return predicate.TravelFulfillment(func(s *sql.Selector) {
		step := newOrderStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.TravelFulfillment) predicate.TravelFulfillment {
	return predicate.TravelFulfillment(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TravelFulfillment) predicate.TravelFulfillment {
	return predicate.TravelFulfillment(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TravelFulfillment) predicate.TravelFulfillment {
	return predicate.TravelFulfillment(sql.NotPredicates(p))
}
